// Extract Message — works for both Facebook Messenger and Instagram DMs
// Meta sends the same webhook structure for both platforms.
// Instagram entries have messaging[].recipient.id matching your IG page-scoped ID
// and the object field is 'instagram' vs 'page' for Messenger.

const body = $input.item.json.body;

const objectType = body.object; // 'page' for FB Messenger, 'instagram' for IG
const entry = body.entry && body.entry[0];

if (!entry) {
  return [{ json: { error: 'No entry in payload', skip: true } }];
}

const messagingEvent = entry.messaging && entry.messaging[0];

if (!messagingEvent || !messagingEvent.message) {
  // Could be a delivery/read receipt — ignore
  return [{ json: { skip: true, reason: 'No message event (delivery/read receipt)' } }];
}

const senderId = messagingEvent.sender.id;
const recipientId = messagingEvent.recipient.id;
const timestamp = messagingEvent.timestamp;
const text = messagingEvent.message.text || '';
const messageId = messagingEvent.message.mid;

// Determine channel
let channel;
if (objectType === 'instagram') {
  channel = 'instagram';
} else {
  channel = 'facebook_messenger';
}

return [{
  json: {
    senderId,
    recipientId,
    text,
    messageId,
    timestamp,
    channel,
    skip: false
  }
}];

// Parse Claude's response.
// Expected format in the assistant reply:
//   ---REPLY---
//   <the text to send back to the user>
//   ---META---
//   action: reply_only | rsvp | escalate
//   event_name: <optional, for rsvp>
//   event_date: <optional, for rsvp>
//   escalate_reason: <optional, for escalate>

const content = $input.item.json.content;
const assistantText = content && content[0] && content[0].text ? content[0].text : '';

// Preserve the upstream fields
const senderId = $('Extract Message').item.json.senderId;
const channel = $('Extract Message').item.json.channel;
const text = $('Extract Message').item.json.text;
const timestamp = $('Extract Message').item.json.timestamp;

let replyText = assistantText;
let action = 'reply_only';
let eventName = '';
let eventDate = '';
let escalateReason = '';

const replySplit = assistantText.split('---REPLY---');
if (replySplit.length > 1) {
  const afterReply = replySplit[1];
  const metaSplit = afterReply.split('---META---');
  replyText = metaSplit[0].trim();

  if (metaSplit.length > 1) {
    const metaBlock = metaSplit[1].trim();
    const lines = metaBlock.split('\n');
    for (const line of lines) {
      const [key, ...vals] = line.split(':');
      const k = key.trim().toLowerCase();
      const v = vals.join(':').trim();
      if (k === 'action') action = v;
      if (k === 'event_name') eventName = v;
      if (k === 'event_date') eventDate = v;
      if (k === 'escalate_reason') escalateReason = v;
    }
  }
}

return [{
  json: {
    senderId,
    channel,
    incomingText: text,
    replyText,
    action,
    eventName,
    eventDate,
    escalateReason,
    timestamp
  }
}];

